const httpItem = $('جلب بيانات النظام (Supabase)').first().json;
const row = Array.isArray(httpItem) ? httpItem[0] : httpItem;
const data = row && row.data ? row.data : row;
const adminEmails = $('إعدادات المستلمين (عدّل هنا)').first().json.adminEmails;

const today = new Date().toISOString().slice(0, 10);

let absentToday = 0, lateToday = 0, partialToday = 0;
Object.keys(data.attendance || {}).forEach(k => {
  if (!k.startsWith(today + '|')) return;
  Object.values(data.attendance[k]).forEach(v => {
    if (v.day === 'absent') absentToday++;
    if (v.day === 'late') lateToday++;
    if (v.periods && v.periods.some(p => p === 'غ')) partialToday++;
  });
});

const visitorsToday = (data.visitors || []).filter(v => v.date === today).length;
const lateArrivalsToday = (data.lateArrivals || []).filter(v => v.date === today).length;
const earlyLeavesToday = (data.earlyLeaves || []).filter(v => v.date === today).length;
const openCases = (data.counselCases || []).filter(c => c.status !== 'مغلقة').length;
const runningTasks = (data.tasks || []).filter(t => t.status === 'جارية').length;

const teacherAbsencesToday = (data.teacherAbsences || []).filter(a => a.date === today);
let lostToday = 0;
teacherAbsencesToday.forEach(a => {
  const covered = Object.values(a.covers || {}).filter(Boolean).length;
  lostToday += Math.max(0, (a.missing || 0) - covered);
});

const rows = [
  ['غائبو اليوم', absentToday],
  ['المتأخرون (حضور يومي)', lateToday],
  ['تأخر صباحي (سجل التأخر)', lateArrivalsToday],
  ['غياب جزئي (حصص)', partialToday],
  ['الزوار اليوم', visitorsToday],
  ['الاستئذان والخروج المبكر', earlyLeavesToday],
  ['حالات إرشادية مفتوحة', openCases],
  ['مهام جارية', runningTasks],
  ['معلمون غائبون اليوم', teacherAbsencesToday.length],
  ['الفاقد التعليمي غير المسدود (حصص)', lostToday]
];

const html = `
<h2>التقرير اليومي - ${data.settings ? data.settings.schoolName : ''} - ${today}</h2>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif">
<tr><th>المؤشر</th><th>القيمة</th></tr>
${rows.map(r => `<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')}
</table>`;

return [{ json: { html, today, adminEmails, schoolName: data.settings ? data.settings.schoolName : '' } }];
